def update_grade_3():
    fname = "data/books/grade_3.json"
    with open(fname, "r", encoding="utf-8") as f:
        data = json.load(f)
    
    updated = 0
    for bk_name in ["nanneri", "nallaram", "nalvazhi"]:
        if bk_name in data["books"]:
            for ch in data["books"][bk_name]["chapters"]:
                cnum = ch["chapterNumber"]
                key = (bk_name, cnum)
                if key in G3_STORIES:
                    ch["story"] = G3_STORIES[key]
                    updated += 1
    
    with open(fname, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    
    print(f"Grade 3 updated successfully! {updated} stories populated.")

if __name__ == "__main__":
    update_grade_3()
